-- Stamina recovers at fixed UTC boundaries everywhere, including while offline.
alter table public.characters
  add column if not exists stamina integer not null default 50,
  add column if not exists stamina_updated_at timestamptz not null default clock_timestamp();
alter table public.characters alter column stamina set default 50;
alter table public.characters drop constraint if exists characters_stamina_check;
alter table public.characters add constraint characters_stamina_check
  check(stamina between 0 and 50);

create or replace function private.stamina_snapshot(stored_stamina integer,anchor timestamptz,observed_at timestamptz)
returns table(stamina integer,stamina_updated_at timestamptz,stamina_next_at timestamptz)
language sql immutable strict security invoker set search_path='' as $$
  with recovered as (
    select least(50,stored_stamina+greatest(0,
      floor(extract(epoch from observed_at)/300)
      -floor(extract(epoch from anchor)/300))*1)::integer as value,
      greatest(anchor,observed_at) as checkpoint
  )
  select value,checkpoint,case when value<50 then
    date_bin(make_interval(secs=>300),checkpoint,'1970-01-01Z'::timestamptz)
      +make_interval(secs=>300) end from recovered;
$$;

-- Future activity RPCs call this inside their receipt/reward transaction.
create or replace function private.spend_activity_stamina(target_id uuid)
returns integer language plpgsql volatile security invoker set search_path='' as $$
declare c public.characters%rowtype; recovered record; observed_at timestamptz;
begin
  if auth.uid() is null or not private.is_registered_player() then
    raise exception 'UNAUTHORIZED' using errcode='42501'; end if;
  if not exists(select 1 from public.characters where id=target_id and user_id=auth.uid()) then
    raise exception 'UNAUTHORIZED' using errcode='42501'; end if;
  perform private.lock_combat_context(array[target_id]);
  select * into c from public.characters where id=target_id and user_id=auth.uid() for update;
  if not found then raise exception 'UNAUTHORIZED' using errcode='42501'; end if;
  observed_at:=clock_timestamp();
  select * into recovered from private.stamina_snapshot(c.stamina,c.stamina_updated_at,observed_at);
  if recovered.stamina<1 then
    raise exception 'INSUFFICIENT_STAMINA' using errcode='P0001'; end if;
  update public.characters set stamina=recovered.stamina-1,
    stamina_updated_at=recovered.stamina_updated_at where id=target_id;
  perform private.notify_training(target_id);
  return recovered.stamina-1;
end;
$$;
revoke all on function private.stamina_snapshot(integer,timestamptz,timestamptz),
  private.spend_activity_stamina(uuid) from public,anon,authenticated;
-- Morale is independent of location and uses fixed server-clock boundaries.
alter table public.characters
  add column if not exists crew_morale numeric not null default 0,
  add column if not exists morale_updated_at timestamptz not null default clock_timestamp();
alter table public.characters drop constraint if exists characters_crew_morale_check;
alter table public.characters add constraint characters_crew_morale_check
  check(crew_morale between -100 and 100
    and crew_morale=round(crew_morale,1));

create or replace function private.morale_snapshot(stored_morale numeric,anchor timestamptz,observed_at timestamptz)
returns table(morale numeric,morale_updated_at timestamptz,morale_next_at timestamptz)
language sql immutable strict security invoker set search_path='' as $$
  with recovered as (
    select sign(stored_morale)*greatest(0,abs(stored_morale)-greatest(0,
      floor(extract(epoch from observed_at)/300)
      -floor(extract(epoch from anchor)/300))*5) as value,
      greatest(anchor,observed_at) as checkpoint
  )
  select round(value,1),checkpoint,case when value<>0 then
    date_bin(make_interval(secs=>300),checkpoint,'1970-01-01Z'::timestamptz)
      +make_interval(secs=>300) end from recovered;
$$;
create or replace function private.morale_multiplier(morale numeric,bonus_bps integer)
returns numeric language sql immutable strict security invoker set search_path='' as $$
  select 1+greatest(-100,least(100,morale))
    /100::numeric*bonus_bps/10000;
$$;
revoke all on function private.morale_snapshot(numeric,timestamptz,timestamptz),
  private.morale_multiplier(numeric,integer) from public,anon,authenticated;
-- Upgrade storage once without changing existing stats, jobs or receipts.
do $training_storage$
declare field text;
begin
  foreach field in array array['crew_attack','crew_defense','crew_speed','crew_accuracy'] loop
    if exists(select 1 from information_schema.columns where table_schema='public'
      and table_name='characters' and column_name=field and data_type='bigint') then
      execute format('alter table public.characters alter column %I type numeric',field);
    end if;
  end loop;
  if exists(select 1 from information_schema.columns where table_schema='private'
    and table_name='training_tiers' and column_name='stat_gain') then
    alter table private.training_tiers rename column stat_gain to efficiency;
    alter table private.training_tiers alter column efficiency type numeric;
    alter table private.training_tiers drop constraint training_tiers_stat_gain_check;
  end if;
end;
$training_storage$;
